# Break My Fix finding 1, generated by Tracefix: set_parsing_settings returns a wrong value.
# Property (docstring): Setting stubs_resolver_allow_py_files to a boolean returns None and makes the parsing setting take that value
# Quote: stubs_resolver_allow_py_files: Whether the stubs resolver should search
# Run it with pytest: it fails for as long as the code breaks this property.

from jsonargparse._common import set_parsing_settings, get_parsing_setting


def test_break_my_fix_1() -> None:
    stubs_resolver_allow_py_files = True
    # The property applies to this input: isinstance(stubs_resolver_allow_py_files, bool)
    result = set_parsing_settings(stubs_resolver_allow_py_files=stubs_resolver_allow_py_files)
    assert (result is None and get_parsing_setting('stubs_resolver_allow_py_files') == stubs_resolver_allow_py_files)
